#include <iostream>

struct Node {
    int data;
    Node* next;
};

Node* divide(Node* head) {
    Node* evenStart = nullptr;
    Node* evenEnd = nullptr;
    Node* oddStart = nullptr;
    Node* oddEnd = nullptr;
    Node* curr = head;

    while (curr != nullptr) {
        if (curr->data % 2 == 0) {
            if (evenStart == nullptr) {
                evenStart = curr;
                evenEnd = evenStart;
            } else {
                evenEnd->next = curr;
                evenEnd = evenEnd->next;
            }
        } else {
            if (oddStart == nullptr) {
                oddStart = curr;
                oddEnd = oddStart;
            } else {
                oddEnd->next = curr;
                oddEnd = oddEnd->next;
            }
        }
        Node* temp = curr;
        curr = curr->next;
        delete temp;
    }

    if (evenStart == nullptr) {
        return head;
    }

    evenEnd->next = oddStart;
    return evenStart;
}

void printList(Node* node) {
    while (node != nullptr) {
        std::cout << node->data << " ";
        node = node->next;
    }
    std::cout << std::endl;
}

int main() {
    Node* head = new Node(0);
    head->next = new Node(1);
    head->next->next = new Node(4);
    head->next->next->next = new Node(6);
    head->next->next->next->next = new Node(9);
    head->next->next->next->next->next = new Node(10);
    head->next->next->next->next->next->next = new Node(11);
    head->next->next->next->next->next->next->next = nullptr;

    std::cout << "Original Linked list: ";
    printList(head);

    head = divide(head);

    std::cout << "Modified Linked list: ";
    printList(head);

    return 0;
}
