This solution first separates the linked list into two separate lists: one for even numbers and one for odd numbers. It then appends the odd list to the even list, resulting in the desired output.

class Solution:
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next

    def solve(self, head: ListNode) -> ListNode:
        if not head:
            return head

        even_head = ListNode()
        odd_head = ListNode()
        even_tail = even_head
        odd_tail = odd_head
        current = head

        while current:
            if current.val % 2 == 0:
                even_tail.next = current
                even_tail = even_tail.next
            else:
                odd_tail.next = current
                odd_tail = odd_tail.next
            current = current.next

        even_tail.next = odd_head.next
        odd_tail.next = None

        return even_head.next
